# Épisodes écrits ensuite (P6, P7…) : episodes/PX.json avec la même structure
# {"id","title","vote":[a,b],"hud","beats":[["img",id,vo,refs,prompt]|["card",vo,desc]], "specs":{...}}
import glob as _glob, json as _json, os as _os
for _f in sorted(_glob.glob(_os.path.join(_os.path.dirname(_os.path.abspath(__file__)), "..", "episodes", "P*.json"))):
    _e = _json.load(open(_f))
    _e["beats"] = [tuple(b) for b in _e["beats"]]
    EPISODES = [e for e in EPISODES if e["id"] != _e["id"]] + [_e]
